# =============================================================================
# EMAIL — send transactional email (password reset, bullpen report delivery)
# Uses Resend (https://resend.com) for the simplest free tier (3000 emails/mo).
# Falls back to no-op if not configured so the rest of the app keeps working.
# =============================================================================
def _email_secrets() -> dict:
    """Pull email config from .streamlit/secrets.toml under [email]."""
    try:
        cfg = dict(st.secrets.get("email", {}))
    except Exception:
        return {}
    return cfg


def email_is_configured() -> bool:
    cfg = _email_secrets()
    # Either Resend API key OR SMTP credentials count as configured
    return bool(cfg.get("resend_api_key") or cfg.get("smtp_host"))


def send_email(to_email: str, subject: str, html_body: str,
                  text_body: str | None = None,
                  attachment_bytes: bytes | None = None,
                  attachment_filename: str | None = None,
                  attachment_mime: str = "application/pdf") -> tuple:
    """Send a transactional email. Returns (success, message).

    Provider preference:
      1. Resend (if [email].resend_api_key is set) — simplest setup
      2. SMTP   (if [email].smtp_host is set)      — works with any SMTP
      3. None   → returns (False, 'Email not configured')

    Args:
        to_email:           recipient
        subject:            subject line
        html_body:          HTML version of the body
        text_body:          plain-text fallback (auto-derived from HTML if None)
        attachment_bytes:   optional file attachment (e.g. PDF bytes)
        attachment_filename:filename for the attachment
        attachment_mime:    MIME type for the attachment

    Designed to fail gracefully — wraps every API call so the caller
    can just check the return tuple.
    """
    if not to_email or "@" not in to_email:
        return False, "Invalid recipient email."
    cfg = _email_secrets()
    from_addr = cfg.get("from_address", "noreply@diamondsportslab.com")
    from_name = cfg.get("from_name", "Diamond Sports Lab")

    if not text_body:
        # crude HTML→text fallback
        import re as _re
        text_body = _re.sub(r"<[^>]+>", "", html_body)
        text_body = _re.sub(r"\s+", " ", text_body).strip()

    # ---------- Provider 1: Resend ----------
    if cfg.get("resend_api_key"):
        try:
            import requests, base64 as _b64
        except Exception as e:
            return False, f"requests library missing: {e}"
        payload = {
            "from":    f"{from_name} <{from_addr}>",
            "to":      [to_email],
            "subject": subject,
            "html":    html_body,
            "text":    text_body,
        }
        if attachment_bytes and attachment_filename:
            payload["attachments"] = [{
                "filename":    attachment_filename,
                "content":     _b64.b64encode(attachment_bytes).decode("ascii"),
                "content_type":attachment_mime,
            }]
        try:
            r = requests.post(
                "https://api.resend.com/emails",
                headers={
                    "Authorization": f"Bearer {cfg['resend_api_key']}",
                    "Content-Type":  "application/json",
                },
                json=payload, timeout=15)
            if r.status_code in (200, 202):
                return True, "Email sent."
            return False, f"Resend API error ({r.status_code}): {r.text[:200]}"
        except Exception as e:
            return False, f"Resend send error: {type(e).__name__}: {e}"

    # ---------- Provider 2: SMTP ----------
    if cfg.get("smtp_host"):
        try:
            import smtplib, ssl
            from email.message import EmailMessage
            msg = EmailMessage()
            msg["Subject"] = subject
            msg["From"]    = f"{from_name} <{from_addr}>"
            msg["To"]      = to_email
            msg.set_content(text_body)
            msg.add_alternative(html_body, subtype="html")
            if attachment_bytes and attachment_filename:
                maintype, _, subtype = attachment_mime.partition("/")
                msg.add_attachment(
                    attachment_bytes,
                    maintype=maintype or "application",
                    subtype=subtype or "octet-stream",
                    filename=attachment_filename)
            host = cfg["smtp_host"]
            port = int(cfg.get("smtp_port", 587))
            user = cfg.get("smtp_user")
            password = cfg.get("smtp_password")
            ctx = ssl.create_default_context()
            with smtplib.SMTP(host, port, timeout=15) as s:
                s.starttls(context=ctx)
                if user and password:
                    s.login(user, password)
                s.send_message(msg)
            return True, "Email sent (SMTP)."
        except Exception as e:
            return False, f"SMTP send error: {type(e).__name__}: {e}"

    return False, ("Email is not configured. Add a [email] section to "
                    ".streamlit/secrets.toml with either 'resend_api_key' "
                    "or smtp_host/smtp_port/smtp_user/smtp_password.")


# =============================================================================
# PASSWORD RECOVERY — request reset → email link → consume token
# =============================================================================
def request_password_reset(email_or_username: str) -> tuple:
    """Generate a reset token, email it to the user. Returns (ok, msg).

    Intentionally returns the same generic message whether or not the
    email matches a real user — prevents account enumeration. The actual
    work happens silently inside.
    """
    import secrets as _secrets
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz

    if not email_or_username or "@" not in str(email_or_username):
        # Allow username too, but normalize
        lookup_by_email = False
        lookup_value = (email_or_username or "").strip().lower()
    else:
        lookup_by_email = True
        lookup_value = _normalize_email(email_or_username)

    generic_msg = ("If an account with that address exists, a reset link "
                    "has been sent. Check your inbox (and spam folder).")

    init_db()
    with _db_conn() as c:
        if lookup_by_email:
            row = c.execute(
                "SELECT id, username, email FROM users "
                "WHERE LOWER(email) = ?", (lookup_value,)).fetchone()
        else:
            row = c.execute(
                "SELECT id, username, email FROM users WHERE username = ?",
                (lookup_value,)).fetchone()

        if row is None:
            # Don't reveal that the account doesn't exist
            return True, generic_msg
        user_id, username, email = row
        if not email:
            return False, ("No email is on file for this account, so we "
                            "can't send a reset link. Contact support.")

        token = _secrets.token_urlsafe(32)
        expires = (_dt.now(_tz.utc) + _td(minutes=30)).isoformat()
        c.execute(
            "UPDATE users SET reset_token = ?, reset_token_expires_at = ? "
            "WHERE id = ?", (token, expires, user_id))

    # Build the reset link
    app_url = (_stripe_secrets().get("app_url")
                  or _email_secrets().get("app_url")
                  or "https://diamondsportslab.com").rstrip("/")
    reset_url = f"{app_url}/?reset_token={token}"

    subject = "Diamond Sports Lab — password reset"
    html_body = f"""
    <div style='font-family:Inter,sans-serif;max-width:560px;'>
      <h2 style='color:#1a2150;'>Reset your password</h2>
      <p>Hi <b>{username}</b>,</p>
      <p>Someone (hopefully you) requested a password reset for your
      Diamond Sports Lab account. Click the link below to choose a new
      password. The link expires in 30 minutes.</p>
      <p style='margin:24px 0;'>
        <a href='{reset_url}' style='background:#1a2150;color:white;
        padding:12px 24px;border-radius:6px;text-decoration:none;
        font-weight:600;'>Reset password</a>
      </p>
      <p style='color:#6b7280;font-size:13px;'>Or paste this into your
      browser: <code>{reset_url}</code></p>
      <p style='color:#6b7280;font-size:13px;'>If you didn't request a
      reset, you can ignore this email — your password won't change.</p>
    </div>
    """
    ok, msg = send_email(email, subject, html_body)
    if not ok:
        # Surface the failure to the operator/log but tell the user
        # the generic message so we still don't leak the account state.
        return True, generic_msg + f"  (send status: {msg})"
    return True, generic_msg


def consume_password_reset_token(token: str, new_password: str) -> tuple:
    """Verify a reset token and set the new password. Returns (ok, msg)."""
    import os
    from datetime import datetime as _dt, timezone as _tz
    if not token or not new_password:
        return False, "Missing token or new password."
    if len(new_password) < 6:
        return False, "Password must be at least 6 characters."
    init_db()
    with _db_conn() as c:
        row = c.execute(
            "SELECT id, reset_token_expires_at FROM users "
            "WHERE reset_token = ?", (token,)).fetchone()
        if row is None:
            return False, "Invalid or already-used reset link."
        uid, expires = row
        try:
            exp_dt = _dt.fromisoformat(expires.replace("Z", "+00:00"))
        except Exception:
            return False, "Reset link is malformed. Request a new one."
        if _dt.now(_tz.utc) > exp_dt:
            return False, "Reset link has expired. Request a new one."
        salt = os.urandom(16)
        c.execute(
            "UPDATE users SET password_hash = ?, salt = ?, "
            "reset_token = NULL, reset_token_expires_at = NULL "
            "WHERE id = ?",
            (_hash_password(new_password, salt), salt.hex(), uid))
    return True, "Password reset. Sign in with your new password."


def _get_stripe():
    """Lazy import + configure the Stripe SDK. Returns the module or None.

    Stripe is an optional dependency — the app runs fine without it, the
    Choose-Tier buttons just show a friendly 'not configured yet' notice.
    """
    cfg = _stripe_secrets()
    if not cfg.get("secret_key"):
        return None
    try:
        import stripe  # type: ignore
    except Exception:
        return None
    stripe.api_key = cfg["secret_key"]
    return stripe


def _stripe_price_id(tier_key: str, billing_cycle: str) -> str | None:
    """Look up the Stripe Price ID for (tier_key, billing_cycle).

    Reads from .streamlit/secrets.toml under
        [stripe.prices]
        individual_monthly = "price_..."
        individual_annual  = "price_..."
        ...
    Returns None if the price isn't configured.
    """
    cfg = _stripe_secrets()
    prices = cfg.get("prices", {}) or {}
    return prices.get(f"{tier_key}_{billing_cycle}")


def _entity_email(kind: str, rec: dict | None) -> str | None:
    """Resolve a billing entity's contact email — used by Stripe so the
    Checkout receipt + Customer Portal default to the right address."""
    if not rec:
        return None
    if kind == "user":
        return rec.get("email")
    # Org billing — use the owner's email
    try:
        owner = rec.get("owner_username")
        if owner:
            owner_rec = get_user_record(owner) or {}
            return owner_rec.get("email")
    except Exception:
        pass
    return None


def create_stripe_checkout_session(tier_key: str,
                                       billing_cycle: str = "monthly",
                                       success_url: str | None = None,
                                       cancel_url: str | None = None) -> tuple:
    """Create a Stripe Checkout Session for the current billing entity.

    Returns (ok, url_or_error_message). On success, redirect the browser
    to the returned URL. On error, surface the message to the user.

    The session carries our (kind, entity_id) in metadata so the on-return
    sync (and any future webhook) can find the right row to update.
    """
    stripe = _get_stripe()
    if stripe is None:
        return False, ("Stripe isn't fully configured yet. "
                        "Add `secret_key` + `prices` under [stripe] in "
                        "`.streamlit/secrets.toml`.")
    if billing_cycle not in ("monthly", "annual"):
        return False, "Invalid billing cycle."
    price_id = _stripe_price_id(tier_key, billing_cycle)
    if not price_id:
        return False, (f"No Stripe Price ID configured for "
                        f"{tier_key} / {billing_cycle}. Add it to "
                        f"[stripe.prices] in secrets.toml.")
    kind, rec = get_billing_entity()
    if rec is None or kind == "none":
        return False, "You must be logged in to subscribe."

    email = _entity_email(kind, rec)
    base_url = (_stripe_secrets().get("app_url") or "").rstrip("/")
    if not base_url:
        # Fall back to a placeholder — Streamlit Cloud users override via
        # the `app_url` secret. The success/cancel URLs CAN be relative
        # for many Stripe flows but it's cleaner to require an absolute.
        base_url = "https://diamondsportslab.com"
    if success_url is None:
        success_url = (f"{base_url}/?stripe_status=success&session_id="
                        f"{{CHECKOUT_SESSION_ID}}")
    if cancel_url is None:
        cancel_url = f"{base_url}/?stripe_status=cancel"

    try:
        params = dict(
            mode="subscription",
            line_items=[{"price": price_id, "quantity": 1}],
            success_url=success_url,
            cancel_url=cancel_url,
            allow_promotion_codes=True,
            metadata={
                "entity_kind": kind,
                "entity_id":   str(rec.get("id")),
                "tier":        tier_key,
                "billing_cycle": billing_cycle,
            },
            subscription_data={
                "metadata": {
                    "entity_kind": kind,
                    "entity_id":   str(rec.get("id")),
                    "tier":        tier_key,
                }},
        )
        # Reuse existing Stripe customer if we have one, otherwise let
        # Stripe create one from the email.
        existing_customer = rec.get("stripe_customer_id")
        if existing_customer:
            params["customer"] = existing_customer
        elif email:
            params["customer_email"] = email
        session = stripe.checkout.Session.create(**params)
        return True, session.url
    except Exception as e:
        return False, f"Stripe error: {type(e).__name__}: {e}"


def sync_subscription_from_stripe(checkout_session_id: str | None = None) -> tuple:
    """Refresh our subscription state from Stripe.

    Called when a user returns from Checkout (success_url) so they don't
    have to wait for a webhook to write the row. Either pass the Checkout
    session ID, or the function falls back to looking up the entity's
    stored stripe_customer_id and reading their active subscriptions.

    Returns (ok, msg).
    """
    stripe = _get_stripe()
    if stripe is None:
        return False, "Stripe not configured."
    try:
        sub = None
        kind = None
        entity_id = None
        tier = None

        if checkout_session_id:
            sess = stripe.checkout.Session.retrieve(
                checkout_session_id,
                expand=["subscription", "customer"])
            kind = (sess.metadata or {}).get("entity_kind")
            try:
                entity_id = int((sess.metadata or {}).get("entity_id"))
            except Exception:
                entity_id = None
            tier = (sess.metadata or {}).get("tier")
            sub = sess.subscription
            customer_id = (sess.customer.id if hasattr(sess.customer, "id")
                            else sess.customer)
        else:
            kind, rec = get_billing_entity()
            if not rec or not rec.get("stripe_customer_id"):
                return False, "No Stripe customer linked to this account."
            customer_id = rec["stripe_customer_id"]
            entity_id = rec.get("id")
            # Find latest active subscription
            subs = stripe.Subscription.list(customer=customer_id,
                                              status="all", limit=5)
            actives = [s for s in subs.data
                          if s.status in ("active", "trialing", "past_due")]
            sub = actives[0] if actives else (subs.data[0] if subs.data else None)
            if sub is not None:
                tier = ((sub.metadata or {}).get("tier")
                          if hasattr(sub, "metadata") else None)

        if sub is None or entity_id is None or kind is None:
            return False, "No subscription found to sync."

        # Map Stripe sub status → our internal status string
        stripe_status = getattr(sub, "status", None) or sub["status"]
        status_map = {
            "active":   "active",
            "trialing": "active",
            "past_due": "past_due",
            "canceled": "canceled",
            "incomplete": "trial",
            "incomplete_expired": "expired",
            "unpaid": "past_due",
            "paused": "canceled",
        }
        our_status = status_map.get(stripe_status, "trial")
        # Subscription end timestamp for renewal display
        try:
            from datetime import datetime as _dt, timezone as _tz
            renew = _dt.fromtimestamp(int(sub["current_period_end"]),
                                          _tz.utc).isoformat()
        except Exception:
            renew = None

        set_subscription(
            kind, entity_id,
            tier=tier or "individual",
            status=our_status,
            renews_at=renew,
            stripe_customer_id=customer_id,
            stripe_subscription_id=getattr(sub, "id", None) or sub.get("id"))
        return True, f"Subscription updated ({our_status})."
    except Exception as e:
        return False, f"Stripe sync error: {type(e).__name__}: {e}"


def create_stripe_portal_session(return_url: str | None = None) -> tuple:
    """Create a Stripe Customer Portal session so the user can manage
    their card, cancel, switch plans, etc. Returns (ok, url_or_error)."""
    stripe = _get_stripe()
    if stripe is None:
        return False, "Stripe not configured."
    kind, rec = get_billing_entity()
    if not rec or not rec.get("stripe_customer_id"):
        return False, ("No Stripe customer on file. Subscribe first, then "
                        "the portal will be available.")
    base_url = (_stripe_secrets().get("app_url") or
                "https://diamondsportslab.com").rstrip("/")
    if return_url is None:
        return_url = f"{base_url}/?stripe_status=returned"
    try:
        portal = stripe.billing_portal.Session.create(
            customer=rec["stripe_customer_id"],
            return_url=return_url)
        return True, portal.url
    except Exception as e:
        return False, f"Stripe portal error: {type(e).__name__}: {e}"


def handle_stripe_return_query():
    """If the user just returned from Stripe Checkout, sync state.

    Streamlit doesn't natively support webhooks. As a pragmatic
    alternative, the success URL carries `stripe_status=success` and
    `session_id={CHECKOUT_SESSION_ID}` in query params. When we detect
    that on page load, we pull the canonical state from Stripe so the
    user sees their subscription as active immediately.

    Safe no-op if no relevant query param is present, or if Stripe is
    not configured.
    """
    if not stripe_is_configured():
        return
    try:
        qp = st.query_params  # Streamlit 1.30+
    except Exception:
        return
    status = qp.get("stripe_status")
    if status == "success":
        session_id = qp.get("session_id")
        ok, msg = sync_subscription_from_stripe(checkout_session_id=session_id)
        if ok:
            st.toast("Subscription activated — welcome aboard.")
        else:
            st.toast(f"Couldn't sync subscription: {msg}", icon="⚠")
        # Clear the query params so we don't re-sync on every rerun
        try:
            for k in ("stripe_status", "session_id"):
                if k in qp:
                    del qp[k]
        except Exception:
            pass
    elif status == "cancel":
        st.toast("Checkout canceled — you can pick a plan whenever you're ready.")
        try:
            del qp["stripe_status"]
        except Exception:
            pass


def get_billing_entity(user: dict | None = None) -> tuple:
    """Return (kind, record) where kind is 'org' or 'user'.

    - Coach role with org → ('org', org_record). The org pays.
    - Athlete role linked to org → still ('org', org_record).
    - Solo athlete (no org) → ('user', user_record). They pay individually.
    - No login → ('none', None).
    """
    if user is None:
        user = current_user_record()
    if user is None:
        return "none", None
    if user.get("org_id"):
        org = get_org_record(user["org_id"])
        if org is not None:
            return "org", org
    return "user", user


def billing_status() -> dict:
    """Return the current entity's billing snapshot.

    Keys:
        kind, entity_id, status, tier, sessions_used, pitches_used,
        can_capture (bool), block_reason (str | None), trial_remaining_sessions,
        trial_remaining_pitches, sample_data (bool — demo-mode is always OK).

    IMPORTANT: While Stripe isn't configured (set up later), every call
    returns can_capture=True so the trial gating is a no-op. Coaches and
    athletes can use the app freely. Once Stripe is wired up, this lifts
    automatically.
    """
    if not stripe_is_configured():
        kind, rec = get_billing_entity()
        return {
            "kind": kind, "entity_id": (rec or {}).get("id"),
            "status": "billing_disabled", "tier": None,
            "sessions_used": 0, "pitches_used": 0,
            "can_capture": True, "block_reason": None,
            "trial_remaining_sessions": None,
            "trial_remaining_pitches": None,
            "sample_data": False,
        }
    if is_demo_mode_active():
        return {
            "kind": "demo", "entity_id": None, "status": "demo",
            "tier": None, "sessions_used": 0, "pitches_used": 0,
            "can_capture": True, "block_reason": None,
            "trial_remaining_sessions": None,
            "trial_remaining_pitches": None,
            "sample_data": True,
        }
    kind, rec = get_billing_entity()
    if rec is None:
        return {
            "kind": "none", "entity_id": None, "status": "logged_out",
            "tier": None, "sessions_used": 0, "pitches_used": 0,
            "can_capture": False,
            "block_reason": "Not logged in.",
            "trial_remaining_sessions": None,
            "trial_remaining_pitches": None,
            "sample_data": False,
        }
    status = rec.get("subscription_status", "trial")
    tier   = rec.get("subscription_tier")
    sess   = int(rec.get("trial_sessions_used", 0) or 0)
    pitch  = int(rec.get("trial_pitches_used", 0) or 0)
    if status == "active":
        return {
            "kind": kind, "entity_id": rec.get("id"),
            "status": status, "tier": tier,
            "sessions_used": sess, "pitches_used": pitch,
            "can_capture": True, "block_reason": None,
            "trial_remaining_sessions": None,
            "trial_remaining_pitches": None,
            "sample_data": False,
        }
    # Trial / past_due / canceled / expired — apply trial caps
    rem_sess  = max(0, TRIAL_SESSIONS_CAP - sess)
    rem_pitch = max(0, TRIAL_PITCHES_CAP  - pitch)
    can = (status == "trial" and rem_sess > 0 and rem_pitch > 0)
    block = None
    if not can:
        if status == "trial":
            block = ("Trial limit reached "
                     f"({sess}/{TRIAL_SESSIONS_CAP} sessions, "
                     f"{pitch}/{TRIAL_PITCHES_CAP} pitches). "
                     "Subscribe to keep capturing.")
        elif status == "past_due":
            block = "Payment past due — please update your card."
        elif status in ("canceled", "expired"):
            block = "Subscription ended — resubscribe to capture more pitches."
        else:
            block = "Subscription required."
    return {
        "kind": kind, "entity_id": rec.get("id"),
        "status": status, "tier": tier,
        "sessions_used": sess, "pitches_used": pitch,
        "can_capture": can, "block_reason": block,
        "trial_remaining_sessions": rem_sess,
        "trial_remaining_pitches":  rem_pitch,
        "sample_data": False,
    }


def increment_trial_counters(sessions_delta: int = 0,
                                pitches_delta: int = 0) -> None:
    """Bump the trial counters on whichever entity owns the subscription.
    No-op if the user is already on an active paid plan, or in demo mode."""
    if is_demo_mode_active():
        return
    kind, rec = get_billing_entity()
    if rec is None or rec.get("subscription_status") == "active":
        return
    table = "organizations" if kind == "org" else "users"
    init_db()
    with _db_conn() as c:
        c.execute(
            f"UPDATE {table} SET trial_sessions_used = "
            f"COALESCE(trial_sessions_used, 0) + ?, "
            f"trial_pitches_used = COALESCE(trial_pitches_used, 0) + ? "
            f"WHERE id = ?",
            (int(sessions_delta), int(pitches_delta), rec["id"]))


def set_subscription(entity_kind: str, entity_id: int, *,
                       tier: str,
                       status: str = "active",
                       renews_at: str | None = None,
                       stripe_customer_id: str | None = None,
                       stripe_subscription_id: str | None = None):
    """Update billing fields on a user or org. Called by Stripe webhook
    or by manual admin actions."""
    table = "organizations" if entity_kind == "org" else "users"
    init_db()
    sets = ["subscription_status = ?", "subscription_tier = ?"]
    params: list = [status, tier]
    if renews_at is not None:
        sets.append("subscription_renews_at = ?")
        params.append(renews_at)
    if stripe_customer_id is not None:
        sets.append("stripe_customer_id = ?")
        params.append(stripe_customer_id)
    if stripe_subscription_id is not None:
        sets.append("stripe_subscription_id = ?")
        params.append(stripe_subscription_id)
    if entity_kind == "org" and tier in SUBSCRIPTION_TIERS:
        sets.append("athlete_cap = ?")
        params.append(SUBSCRIPTION_TIERS[tier]["athlete_cap"])
    params.append(entity_id)
    with _db_conn() as c:
        c.execute(f"UPDATE {table} SET {', '.join(sets)} WHERE id = ?",
                    params)


def render_trial_status_banner():
    """Sidebar banner showing trial progress + Subscribe button.
    No-op when billing isn't enabled yet (Stripe not configured)."""
    if not stripe_is_configured():
        return
    bs = billing_status()
    if bs["status"] == "active" or bs["sample_data"]:
        return
    if bs["status"] == "logged_out":
        return
    sess = bs["sessions_used"]
    pitch = bs["pitches_used"]
    rem_sess = bs["trial_remaining_sessions"]
    rem_pitch = bs["trial_remaining_pitches"]
    color = "#22c55e"
    label = "Free trial"
    if not bs["can_capture"]:
        color = "#ef4444"
        label = "Trial ended"
    elif (rem_sess or 0) <= 1 or (rem_pitch or 0) <= 5:
        color = "#d4a634"
        label = "Trial — almost up"
    st.markdown(
        f"<div style='background:#1e293b;border-left:4px solid {color};"
        f"border-radius:8px;padding:10px 14px;margin:8px 0;'>"
        f"<div style='font-size:10px;letter-spacing:0.10em;font-weight:700;"
        f"color:{color};text-transform:uppercase;'>{label}</div>"
        f"<div style='color:#cbd5e1;font-size:12px;margin-top:4px;'>"
        f"{sess}/{TRIAL_SESSIONS_CAP} sessions · "
        f"{pitch}/{TRIAL_PITCHES_CAP} pitches used</div>"
        f"</div>",
        unsafe_allow_html=True)
    if st.button("Subscribe", key="trial_subscribe_btn",
                  use_container_width=True, type="primary"):
        st.session_state["show_billing_modal"] = True
        st.rerun()


def render_billing_modal_if_requested():
    """Full pricing card + Stripe Checkout launch."""
    if not st.session_state.get("show_billing_modal"):
        return
    st.markdown("---")
    # If they already have an active subscription, surface the Stripe
    # Customer Portal button up top instead of just showing plans again.
    kind, bill_rec = get_billing_entity()
    bill_status = (bill_rec or {}).get("subscription_status")
    if bill_status == "active" and stripe_is_configured():
        cur_tier_key = (bill_rec or {}).get("subscription_tier")
        cur_tier = SUBSCRIPTION_TIERS.get(cur_tier_key, {})
        st.success(
            f"Active subscription: **{cur_tier.get('label', cur_tier_key)}**. "
            "Use Manage to update card, switch plan, or cancel.")
        if st.button("Manage subscription (Stripe portal)",
                      key="open_stripe_portal",
                      type="primary",
                      use_container_width=True):
            ok, msg = create_stripe_portal_session()
            if ok:
                st.markdown(
                    f"<meta http-equiv='refresh' content='0; url={msg}'>"
                    f"<a href='{msg}' target='_self'>"
                    f"Open Stripe Customer Portal →</a>",
                    unsafe_allow_html=True)
                st.stop()
            else:
                st.error(msg)
        st.markdown("---")
    st.subheader("Choose a plan")
    st.caption(
        "All plans start with a 14-day trial limited to "
        f"{TRIAL_SESSIONS_CAP} sessions or {TRIAL_PITCHES_CAP} pitches. "
        "Upgrade anytime — keep your captured data either way. Cancel "
        "anytime from the Billing tab.")
    cycle = st.radio("Billing cycle", ["Annual (save ~30%)", "Monthly"],
                       horizontal=True, key="billing_cycle")
    is_annual = cycle.startswith("Annual")
    cols = st.columns(len(SUBSCRIPTION_TIERS))
    for i, (key, t) in enumerate(SUBSCRIPTION_TIERS.items()):
        price = t["annual_usd"] if is_annual else t["monthly_usd"]
        unit = "/yr" if is_annual else "/mo"
        with cols[i]:
            st.markdown(
                f"<div style='background:#1e293b;border:1px solid #334155;"
                f"border-radius:12px;padding:18px 16px;height:100%;'>"
                f"<div style='font-size:11px;letter-spacing:0.10em;font-weight:700;"
                f"color:#94a3b8;text-transform:uppercase;'>{t['label']}</div>"
                f"<div style='font-size:30px;font-weight:800;color:#f1f5f9;"
                f"margin:8px 0 2px 0;'>${price:.0f}<span style='font-size:14px;"
                f"font-weight:500;color:#94a3b8;'>{unit}</span></div>"
                f"<div style='font-size:12px;color:#cbd5e1;line-height:1.5;"
                f"min-height:48px;'>{t['blurb']}</div>"
                f"<div style='font-size:11px;color:#64748b;margin-top:6px;'>"
                f"Up to {t['athlete_cap']} athlete"
                f"{'s' if t['athlete_cap'] > 1 else ''}</div>"
                f"</div>",
                unsafe_allow_html=True)
            if st.button(f"Choose {t['label']}",
                          key=f"choose_{key}_{cycle}",
                          use_container_width=True):
                if stripe_is_configured():
                    cycle_key = "annual" if is_annual else "monthly"
                    ok, msg = create_stripe_checkout_session(
                        tier_key=key, billing_cycle=cycle_key)
                    if ok:
                        # `msg` is the Checkout URL. Redirect the browser
                        # via a meta-refresh / window.location since
                        # Streamlit can't do a server-side redirect.
                        st.markdown(
                            f"<meta http-equiv='refresh' content='0; url={msg}'>"
                            f"<a href='{msg}' target='_self'>"
                            f"Continue to secure checkout →</a>",
                            unsafe_allow_html=True)
                        st.stop()
                    else:
                        st.error(msg)
                else:
                    st.warning(
                        "Billing isn't fully turned on yet. The price tiers "
                        "are locked in, but card processing needs the Stripe "
                        "account to be created and the API keys to be pasted "
                        "into `.streamlit/secrets.toml`. Once that's done "
                        "this button completes the subscription.")
    if st.button("Close", key="close_billing_modal",
                  use_container_width=True):
        st.session_state["show_billing_modal"] = False
        st.rerun()


def list_athletes(include_archived: bool = False,
                    user_scope: str | None = "auto",
                    ) -> list[dict]:
    """List athletes filtered to the active user.

    Scoping rules (when user_scope='auto'):
        - Demo mode on → athletes with created_by='__demo__'.
        - Coach     → all athletes where org_id = coach's org, OR
                      athletes the coach created (covers solo coaches with
                      no org_id set during migration).
        - Athlete   → only the athlete linked to this user account.
        - Logged out (tests) → all athletes (no filter).

    user_scope override:
        - explicit string: return only athletes with that created_by tag
          (legacy compatibility for the demo-loader / sample seeding).
        - None: no filter (admin / test usage).
    """
    init_db()
    explicit_created_by = None
    if user_scope == "auto":
        if is_demo_mode_active():
            tier = current_demo_tier() or "individual"
            spec = DEMO_TIERS.get(tier, DEMO_TIERS["individual"])
            explicit_created_by = spec["tag"]
        else:
            user = current_user_record()
            if user is None:
                user_scope = None
            elif user.get("role") == "admin":
                # Admin sees everything (no filter)
                user_scope = None
            elif user.get("role") == "athlete":
                # Athletes see exactly their linked athlete
                with _db_conn() as c:
                    q = "SELECT * FROM athletes WHERE id = ?"
                    if not include_archived:
                        q += " AND archived = 0"
                    rows = c.execute(
                        q, (user.get("linked_athlete_id"),)).fetchall()
                return [dict(r) for r in rows]
            else:
                # Coach — scope by org_id (or fall back to created_by)
                org_id = user.get("org_id")
                with _db_conn() as c:
                    q = "SELECT * FROM athletes WHERE 1=1"
                    params: list = []
                    if org_id:
                        q += " AND (org_id = ? OR created_by = ?)"
                        params.extend([org_id, user.get("username")])
                    else:
                        q += " AND created_by = ?"
                        params.append(user.get("username"))
                    if not include_archived:
                        q += " AND archived = 0"
                    q += " ORDER BY name"
                    return [dict(r) for r in c.execute(q, params).fetchall()]
    elif isinstance(user_scope, str):
        explicit_created_by = user_scope

    with _db_conn() as c:
        q = "SELECT * FROM athletes WHERE 1=1"
        params: list = []
        if explicit_created_by is not None:
            q += " AND created_by = ?"
            params.append(explicit_created_by)
        if not include_archived:
            q += " AND archived = 0"
        q += " ORDER BY name"
        return [dict(r) for r in c.execute(q, params).fetchall()]


